function buildLangMenu(){
  const m=$('langMenu'),btn=$('langBtn');if(!m)return;
  m.innerHTML=Object.entries(LANG_NAMES).map(([k,v])=>`<button type="button" data-lang="${k}" role="menuitem">${v}</button>`).join('');
  m.setAttribute('role','menu');
  m.querySelectorAll('button[data-lang]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();applyLang(b.dataset.lang);if(btn)btn.focus()}))}
