let loadingTimer = null;
async function solve(forceIgnoreClarification = false){
  if(!(await calcelfEnsurePrivacy())) return;
  let s = await session();
  if (!s) { if (sb) { try { await sb.auth.signInAnonymously(); s = await session(); } catch (e) { console.error('Auto anonymous login failed:', e); } } if (!s) { openModal('authModal'); return; } }
  const textInput = $('text').value.trim();
  if(!imageBase64 && !textInput){ toast(t('needInput')); return; }
  const turnstileToken = token();
  if(window.turnstile && cfg.turnstileSiteKey && !turnstileToken && !s){ toast('Please complete the human check.'); return; }
  const data={ imageBase64, imageMime:$('file').files[0]?.type||'image/jpeg', text:textInput, stage:$('stage').value, language:currentLang, animationRequested:$('wantAnim').checked, turnstileToken: turnstileToken || '', installId, forceIgnoreClarification };
  const loadingTexts={ 'zh-CN':['📖 正在阅读题目…','🧠 正在思考解法…','✍️ 正在生成讲解…','✨ 即将完成…'], 'zh-TW':['📖 正在閱讀題目…','🧠 正在思考解法…','✍️ 正在產生講解…','✨ 即將完成…'], en:['📖 Reading the problem…','🧠 Thinking through the solution…','✍️ Writing the walkthrough…','✨ Almost done…'], ja:['📖 問題を読んでいます…','🧠 解き方を考えています…','✍️ 解説を作成しています…','✨ もうすぐ完了です…'], ko:['📖 문제를 읽는 중…','🧠 풀이를 생각하는 중…','✍️ 설명을 만드는 중…','✨ 거의 완료되었습니다…'], fa:['📖 در حال خواندن مسئله…','🧠 در حال فکر کردن به راه‌حل…','✍️ در حال ساخت توضیح…','✨ تقریباً تمام شد…'] };
  const texts = loadingTexts[currentLang] || loadingTexts['en'];
  let textIndex = 0; const lTextEl = $('loadingText'); if (lTextEl) lTextEl.textContent = texts[0];
  clearInterval(loadingTimer); loadingTimer = setInterval(() => { textIndex = (textIndex + 1) % texts.length; if (lTextEl) lTextEl.textContent = texts[textIndex]; }, 3000);
  $('loading').classList.add('show'); setStatus(t('analyze'),false);
  try{
    const r=await fetch('/api/solve',{method:'POST',headers:authHeader(s),body:JSON.stringify(data)});
    const j=await r.json();
    if (j.need_clarification) { $('loading').classList.remove('show'); clearInterval(loadingTimer); const userConfirmed = confirm(j.clarification_msg + "\n\n是否忽略图片，仅使用文字解题？"); if (userConfirmed) { imageBase64 = null; $('preview').style.display='none'; $('file').value=''; await solve(true); } return; }
    if (!r.ok) { if (j.code === 'ANON_LIMIT_REACHED' || j.code === 'INSUFFICIENT_CREDITS') { setStatus(t('notEnough'), true); setTimeout(() => { openModal('authModal'); }, 1500); $('loading').classList.remove('show'); clearInterval(loadingTimer); return; } throw Error(j.error||t('genericError')); }
    currentResult=j.result; setText('credits',j.credits); $('result').style.display='block'; setText('question',currentResult.question_text||''); setText('subject',currentResult.subject||'');
    const ss=(currentResult.solutions||[]).slice(0,3); setText('count',ss.length+' '+(currentLang==='zh-CN'?'种':currentLang==='zh-TW'?'種':currentLang==='ja'?'通り':currentLang==='ko'?'가지':currentLang==='ar'?'طريقة':currentLang==='fa'?'روش':'method(s)'));
$('solutions').innerHTML=ss.map((sol,i)=>`<div class="solution"><div style="display:flex;gap:8px;align-items:center"><b>💡 ${esc(sol.name||('Method '+(i+1)))}</b>${sol.recommended?'<span class="pill">⭐</span>':''}</div>${(sol.steps||[]).map((st,idx)=>{
  const num = st.step ?? st.n ?? st.index ?? st.num ?? st.order ?? (idx+1);
  const desc = st.description ?? st.text ?? st.desc ?? st.content ?? st.body ?? st.explanation ?? '';
  const formula = st.formula ?? st.equation ?? st.math ?? st.expression ?? '';
  return `<div class="step"><div class="num">${esc(num)}</div><div>${esc(desc)}${formula?`<div class="formula">${esc(formula)}</div>`:''}</div></div>`;
}).join('')}</div>`).join('');
    if(window.MathJax)try{MathJax.typesetPromise()}catch{};
    currentSession={summary:(currentResult.question_text||'')+'\n'+(currentResult.answer||'')};
    $('chat').innerHTML=`<div class="msg assistant">${esc(currentLang==='zh-CN'?'你好！围绕这道题继续问我。':'Hi! Ask me anything about this problem.')}</div>`;
    if (j.is_anonymous) { setStatus(`🎁 您当前是免费体验模式，今日剩余 ${j.remaining_free} 次免费解题机会。`, false); }
    const isGrace = j.is_grace === true; if (isGrace && !j.is_anonymous) { setStatus('🎁 已为您开启关怀模式，本次服务已消耗完剩余额度，欢迎下次充值。', false); }
    if($('wantAnim').checked && currentResult.animation_worthy) await animation(isGrace);
    if (!j.is_anonymous) setStatus(t('done'));
  }catch(e){ setStatus('❌ '+e.message,true); $('loading').classList.remove('show'); clearInterval(loadingTimer); }
  finally{ $('loading').classList.remove('show'); clearInterval(loadingTimer); if(window.turnstile&&cfg.turnstileSiteKey)try{if(window.tsWidget)turnstile.reset(window.tsWidget)}catch{} }
}

