function openModal(id){const el=$(id);if(el)el.classList.add('open')}
function toast(x){setStatus(x,false);setTimeout(()=>{const el=$('status');if(el)el.className='status'},3500)}
function setStatus(x,err=false){
  const el=$('status');
  if(el){
    if(err && (x.includes('额度') || x.includes('Credits') || x.includes('小精灵'))) {
       el.innerHTML = `<div style="display:flex; align-items:center; justify-content:center; gap:10px; font-size:16px; font-weight:bold; padding: 5px;"> <img src="/calcelf-logo.png" style="width:45px; height:45px; animation: bounce 1.5s infinite ease-in-out;"> <span>${x.replace('❌','')}</span> </div>`;
    } else { el.textContent = x; }
    el.className='status show '+(err?'err':'ok');
  }
}
